version.content:
pipeline {
    agent any
    options {
        // 配置构建保留策略
        buildDiscarder(logRotator(
            numToKeepStr: '10',        // 最多保留 10 个构建
            // daysToKeepStr: '10',       // 保留 10 天内的构建
            artifactNumToKeepStr: '10', // 最多保留 10 个构建的制品
            // artifactDaysToKeepStr: '5' // 保留 5 天内的构建制品
        ))
    }
    parameters {
        choice(
            name: 'OPERATION',
            choices: ['deploy', 'rollback', 'start', 'stop', 'restart'],
            description: '操作类型：部署/回滚/启动/停止/重启'
        )
        string(name: 'ENV', defaultValue: 'PROD', description: '环境：DEV/TEST/UAT/PRE/PROD')
        string(name: 'APP_NAME', defaultValue: 'code-scan', description: '应用名称')
        string(name: 'VERSION', defaultValue: '1.1.2', description: '镜像标签（部署时必填）')
        string(name: 'ROLLBACK_TAG', defaultValue: '', description: '回滚标签（回滚时优先使用）')
    }

    environment {
        // 镜像仓库配置
        DOCKER_REGISTRY = 'harbor.bigdata.com:12021'
        DOCKER_IMAGE_PREFIX = "${DOCKER_REGISTRY}/devops"

        // 远程服务器配置（路径动态化）
        REMOTE_HOST = '20.48.115.6'
        REMOTE_USER = 'root'
        REMOTE_PATH = "/data/${params.APP_NAME}"
        // 注意：此变量会被同名参数覆盖，如不需要可删除
        APP_NAME = "0.0.1-SNAPSHOT"
        // Git 配置
        GIT_URL = 'http://20.48.1.132:12001/devsecops/opsservice/code_scan.git'
        GIT_BRANCH = 'pro'
        GIT_CREDENTIALS_ID = '668d4a76-2bba-4aed-9693-5b6e5625e4a7'

        // AWX 配置（仅部署时触发）
        AWX_URL = 'http://20.12.18.199:8013'
        AWX_WEBHOOK_TOKEN = 'IhDJxIyQvZKaawrdSoDV'
        AWX_JT_ID = '12'
        TARGET_HOST = '20.31.132.40'
        COMPOSE_PATH = '/data/bigdata-sendmsg'

        // 凭据 ID（需在 Jenkins 中配置）
        SSH_CREDENTIALS_ID = 'ssh-credential-id'
        HARBOR_CREDENTIALS_ID = 'harbor-credential-id'
        MINIO_CREDS = 'c44a58e0-b640-471c-ab76-a667bb5e4fcb'
        ARTIFACT_BUCKET = 'deploy'
    }

    stages {
        stage('Show Version') {
            steps {
                echo "构建编号是：${env.BUILD_NUMBER}"
                echo "构建标签是：${env.BUILD_TAG}"
                echo "构建ID是：${env.BUILD_ID}"
                echo "任务名称是：${env.JOB_NAME}"
                sh 'printenv'
            }
        }

        stage('代码检出') {
            // when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    echo "检出代码分支: ${env.GIT_BRANCH}"
                    git branch: env.GIT_BRANCH,
                        credentialsId: env.GIT_CREDENTIALS_ID,
                        url: env.GIT_URL
                    sh 'git rev-parse --short HEAD > GIT_COMMIT_SHORT'
                    def gitCommit = readFile('GIT_COMMIT_SHORT').trim()
                    env.GIT_COMMIT_SHORT = gitCommit
                    echo "代码检出完成，Commit: ${env.GIT_COMMIT_SHORT}"
                }
            }
        }

        stage('Docker 构建与推送') {
            when { expression { params.OPERATION == 'deploy' } }
            steps {
                script {
                    def imageTag = params.VERSION ?: "build-${BUILD_NUMBER}-${env.GIT_COMMIT_SHORT}"
                    env.LATEST_IMAGE_TAG = imageTag
                    def fullImageName = "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${imageTag}"
                    echo "构建镜像: ${fullImageName}"
                }

                // 登录 Docker 仓库
                withCredentials([
                    usernamePassword(
                        credentialsId: env.HARBOR_CREDENTIALS_ID,
                        usernameVariable: 'HARBOR_USER',
                        passwordVariable: 'HARBOR_PASS'
                    )
                ]) {
                    sh """
                        docker login ${env.DOCKER_REGISTRY} -u \${HARBOR_USER} -p \${HARBOR_PASS}
                    """
                }

                script {
                    def fullImageName = "${env.DOCKER_IMAGE_PREFIX}/${params.APP_NAME}:${env.LATEST_IMAGE_TAG}"
                    // 如果 Dockerfile 在子目录 bigdata-sendmsg 中，取消注释 dir 块
                    // dir('bigdata-sendmsg') {
                    sh """
                        docker build -t ${fullImageName} .
                        docker push ${fullImageName}
                    """
                    // }
                    writeFile file: "${WORKSPACE}/.image_tag", text: env.LATEST_IMAGE_TAG
                    echo "镜像推送完成: ${fullImageName}"
                }
            }   // 关闭 steps
        }       // 关闭 stage
    }           // 关闭 stages

    post {
        always {
            echo '========================================'
            echo " Pipeline 执行完成 "
            echo " 最终状态: ${currentBuild.result ?: 'SUCCESS'}"
            echo '========================================'
        }
        success {
            echo "✅ 操作成功完成!"
        }
        failure {
            echo "❌ 操作失败，请检查日志!"
        }
    }
}
